import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """Readiness slack: (machine_free - job_ready) scaled by its max abs and clipped to [-1, 1]."""
    d = machine_free - job_ready
    s = np.abs(d).max() if d.size else 0.0
    return np.clip(d / (s + 1e-9), -1.0, 1.0)

import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """Relative load difference: (current machine backlog - next machine backlog) / (sum + eps), 0 for last ops."""
    denom = machine_work_left + next_machine_work + 1e-9
    raw = (machine_work_left - next_machine_work) / denom
    return np.where(job_ops_left > 1, raw, 0.0)

import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """Contrast of job work-left vs processing time, each z-scored within the candidate set."""
    proc = np.asarray(proc_time, float)
    jwl = np.asarray(job_work_left, float)

    def z(x):
        med = np.median(x)
        spread = float(np.max(x) - np.min(x))
        if spread <= 1e-9 * (abs(med) + 1.0):
            return np.zeros_like(x)
        return (x - med) / spread

    return 0.5 * (z(jwl) - z(proc))

import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """Forced wait of the decision machine for this candidate, in units of the job's average remaining op length: idle / (idle + per_op)."""
    per_op = job_work_left / np.maximum(job_ops_left, 1.0)
    idle = np.maximum(0.0, job_ready - machine_free)
    return idle / (idle + per_op + 1e-9)

import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """tanh of (forced idle minus the op's own duration) per unit of the job's remaining work."""
    idle = np.maximum(0.0, job_ready - machine_free)
    return np.tanh((idle - proc_time) / (job_work_left + 1.0))

