import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """Post-choice idle gap: wait until the earliest other candidate becomes ready after this op finishes, normalised."""
    k = len(proc_time)
    if k < 2:
        return np.zeros(k)
    s = np.sort(job_ready)
    m1 = s[0]
    m2 = s[1]
    min_other = np.where(job_ready > m1, m1, m2)
    finish = np.maximum(machine_free, job_ready) + proc_time
    gap = np.maximum(0.0, min_other - finish)
    return gap / (gap + proc_time + 1.0)

import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """job_ops_left normalised by the max job_ops_left over the candidate set (0 if max <= 0)."""
    m = np.max(job_ops_left) if job_ops_left.size > 0 else 0.0
    if m <= 0:
        return np.zeros_like(proc_time)
    return job_ops_left / m

import numpy as np

def feature(proc_time, job_ready, job_work_left, job_ops_left, next_machine_work, machine_free, machine_work_left):
    """1 if the candidate's slack (machine_free - job_ready) is at or above max(0, median slack), else 0."""
    slack = machine_free - job_ready
    thr = max(0.0, float(np.median(slack)))
    return (slack >= thr).astype(float)
